  "겁 많은 놈이 관찰을 잘한다. 겁도 재능이다 아이가.": [
    { by: "grit_captain", text: "겁먹고 멈추지만 않으면 된다." },
  ],
  // ── 주술사 ──
  "제자 자랑 좀 할게요. 제가 맡은 1학년 셋 중 막내가 오늘 저 없이 해냈어요. 이게 얼마나 대단한 건지 아세요?":
    [{ by: "mountain_preacher", text: "아이들은 어른이 없을 때 자랍니다. 아실 텐데요." }],
